import React, { useState, useEffect } from 'react';

const EventLogStream = () => {
  // Mock data for demonstration. In production, this would come from HBTF via WebSocket.
  const [logs, setLogs] = useState([
    { id: 1, timestamp: '2026-07-30 12:20:01', level: 'INFO', message: 'Node `swarm-node-alpha-001` registered.' },
    { id: 2, timestamp: '2026-07-30 12:20:15', level: 'WARN', message: 'Task `data-ingest-job-42` exceeded latency threshold.' },
    { id: 3, timestamp: '2026-07-30 12:20:30', level: 'INFO', message: 'Resource allocation updated for `compute-cluster-beta`.' },
    { id: 4, timestamp: '2026-07-30 12:20:45', level: 'ERROR', message: 'Disk I/O failure on `storage-unit-gamma-003`. Initiating failover.' },
    { id: 5, timestamp: '2026-07-30 12:21:00', level: 'INFO', message: 'New task `analytics-report-gen` started on `swarm-node-delta-005`.' },
    { id: 6, timestamp: '2026-07-30 12:21:10', level: 'DEBUG', message: 'Telemetry stream heartbeat received from `swarm-node-epsilon-002`.' },
    { id: 7, timestamp: '2026-07-30 12:21:25', level: 'INFO', message: 'Configuration update applied across `network-segment-zeta`.' },
    { id: 8, timestamp: '2026-07-30 12:21:40', level: 'WARN', message: 'High memory usage detected on `swarm-node-eta-007`.' },
  ]);

  // Simulate new log entries arriving
  useEffect(() => {
    const interval = setInterval(() => {
      const newLog = {
        id: logs.length + 1,
        timestamp: new Date().toISOString().slice(0, 19).replace('T', ' '),
        level: ['INFO', 'WARN', 'ERROR', 'DEBUG'][Math.floor(Math.random() * 4)],
        message: `Simulated event ${logs.length + 1} from Swarm OS.`,
      };
      setLogs((prevLogs) => [newLog, ...prevLogs].slice(0, 10)); // Keep last 10 logs
    }, 5000); // Add a new log every 5 seconds

    return () => clearInterval(interval);
  }, [logs]);

  const getLevelColor = (level) => {
    switch (level) {
      case 'INFO': return 'text-swarm-accent';
      case 'WARN': return 'text-swarm-warning';
      case 'ERROR': return 'text-swarm-danger';
      case 'DEBUG': return 'text-gray-500';
      default: return 'text-gray-300';
    }
  };

  return (
    <div className="h-96 flex flex-col">
      <h3 className="text-lg font-semibold text-white mb-4">Recent Event Log</h3>
      <div className="flex-1 overflow-y-auto pr-2">
        {logs.map((log) => (
          <div key={log.id} className="flex items-start text-sm mb-2 p-2 rounded hover:bg-gray-700 transition-colors duration-150">
            <span className="font-mono text-gray-500 mr-4 min-w-[120px]">{log.timestamp}</span>
            <span className={`font-bold mr-4 min-w-[60px] ${getLevelColor(log.level)}`}>{log.level}</span>
            <span className="flex-1 text-gray-300">{log.message}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default EventLogStream;